const game = new GF.Game({
  id:'titan-core-reforged-v2', title:'TITAN CORE: REFORGED', width:960, height:540,
  palette:['#14D9FF','#FF3B81','#FFBF3F','#07111F'], background:'#07111F', seed:77421
});
// The micro-engine owns logical coordinates; explicitly size its backing surface for crisp full-arena renders.
game.canvas.width=960; game.canvas.height=540;

const C={navy:'#07111F',cyan:'#14D9FF',pink:'#FF3B81',gold:'#FFBF3F',white:'#EAFBFF',dim:'#7CA1B8'};

function panel(ctx,x,y,w,h,edge){
  ctx.fillStyle='rgba(4,14,31,.88)';ctx.fillRect(x,y,w,h);
  ctx.strokeStyle=edge;ctx.globalAlpha=.62;ctx.lineWidth=1;ctx.strokeRect(x+.5,y+.5,w-1,h-1);ctx.globalAlpha=1;
}
function hex(ctx,x,y,r){
  ctx.beginPath();for(let i=0;i<6;i++){const a=i*Math.PI/3+Math.PI/6;const px=x+Math.cos(a)*r,py=y+Math.sin(a)*r;i?ctx.lineTo(px,py):ctx.moveTo(px,py);}ctx.closePath();
}

game.add('play',{
  init(){this.reset();},
  reset(){
    this.p={x:480,y:300,r:18,hp:100,maxHp:100,damage:8,pulse:82,angle:0,fire:0,invuln:0,level:1};
    this.drones=[];this.shots=[];this.hostile=[];this.shards=[];
    this.phase='opening';this.titan=null;this.scoreKills=0;this.salvage=0;this.spent=0;
    this.spawnTimer=0;this.ringSpin=0;this.musicTimer=.6;this.bonusTime=25;
    this.hudSent=false;this.titanSent=false;this.attackSent=false;this.choice='';
    this.spawnDrone(650,185,8);this.spawnDrone(720,380,8);this.spawnDrone(790,260,8);
  },
  spawnDrone(x,y,hp){
    if(this.drones.length>=15)return;
    this.drones.push({x,y,hp:hp||8,max:hp||8,r:14,fire:.7+(game.rng()*.4),flash:0,contact:0});
  },
  spawnTitan(){
    if(this.titan)return;
    this.phase='titan';
    this.titan={x:706,y:270,r:62,hp:108,max:108,flash:0,fire:.72,stomp:2.1,spin:0,segments:4,dead:false};
    this.spawnDrone(825,126,20);this.spawnDrone(816,425,20);
    game.shake(6,.35);game.flash(C.cyan,.16);
    GF.Sfx.melody([[130,.1],[180,.1],[240,.16]],{type:'sawtooth',vol:.16});
  },
  fire(){
    const p=this.p;let tx=game.input.pointer.x,ty=game.input.pointer.y;
    const target=this.titan&&!this.titan.dead?this.titan:this.drones[0];
    if(!game.input.pointer.down&&target){tx=target.x;ty=target.y;}
    let dx=tx-p.x,dy=ty-p.y,dd=Math.hypot(dx,dy)||1;dx/=dd;dy/=dd;p.angle=Math.atan2(dy,dx);
    this.shots.push({x:p.x+dx*24,y:p.y+dy*24,vx:dx*690,vy:dy*690,r:5,life:1.2});
    p.fire=.115;
    game.burst(p.x+dx*23,p.y+dy*23,{count:3,speed:80,size:2,life:.18,colors:[C.cyan,C.white],gravity:0,spread:.38,dir:p.angle});
    GF.Sfx.beep({freq:660,to:980,dur:.045,type:'square',vol:.07});
  },
  hurt(n,x,y){
    const p=this.p;if(p.invuln>0)return;p.invuln=.32;p.hp=Math.max(0,p.hp-n);
    game.shake(5,.16);game.flash(C.pink,.11);game.burst(x,y,{count:10,speed:145,size:3,life:.34,colors:[C.pink,C.gold],gravity:55});
    GF.Sfx.noise({dur:.07,vol:.1,freq:820});if(p.hp<=0)game.gameOver({message:'CORE COLLAPSED'});
  },
  spill(x,y,count){for(let k=0;k<count;k++)this.shards.push({x,y,vx:(game.rng()-.5)*150,vy:(game.rng()-.5)*150,life:8});},
  killDrone(i){
    const d=this.drones[i];if(!d)return;this.drones.splice(i,1);this.scoreKills++;
    game.addScore(this.phase==='bonus'?40:20);game.hitStop(.045);game.shake(4,.12);
    game.burst(d.x,d.y,{count:16,speed:175,size:3,life:.45,colors:[C.cyan,C.gold,C.white],gravity:90});
    this.spill(d.x,d.y,3);GF.Sfx.noise({dur:.06,vol:.1,freq:1750});
  },
  hitTitan(){
    const t=this.titan,p=this.p;if(!t||t.dead)return;
    t.hp-=p.damage;t.flash=.15;
    game.burst(t.x,t.y,{count:12,speed:190,size:3,life:.33,colors:[C.cyan,C.white,C.gold],gravity:60});
    game.shake(3,.1);GF.Sfx.noise({dur:.055,vol:.1,freq:2200});
    if(!this.attackSent&&game.time>1.25&&game.score>0){this.attackSent=true;game.event('attack_landed',{target:'HEX-FRAME TITAN',damage:p.damage});}
    const seg=Math.max(0,Math.ceil(t.hp/27));
    if(seg<t.segments&&t.hp>0){t.segments=seg;game.addScore(60);game.hitStop(.08);game.flash(C.gold,.2);game.burst(t.x,t.y,{count:26,speed:240,size:5,life:.62,colors:[C.gold,C.pink],gravity:170});}
    if(t.hp<=0)this.killTitan();
  },
  killTitan(){
    const t=this.titan;t.dead=true;this.phase='choice';game.addScore(250);game.hitStop(.08);game.shake(14,.62);game.flash(C.gold,.45);
    game.burst(t.x,t.y,{count:70,speed:320,size:6,life:1,colors:[C.gold,C.cyan,C.pink,C.white],gravity:110});this.spill(t.x,t.y,12);
    GF.Sfx.melody([[110,.11],[165,.11],[330,.2]],{type:'sawtooth',vol:.22});
  },
  buyUpgrade(){
    if(this.salvage<3||this.phase==='choice'||game.time<=1.25)return;
    const p=this.p;this.salvage-=3;this.spent+=3;let before,after,stat;
    if(p.level%3===1){stat='damage';before=p.damage;p.damage+=3;after=p.damage;}
    else if(p.level%3===2){stat='maxHp';before=p.maxHp;p.maxHp+=20;p.hp=Math.min(p.maxHp,p.hp+20);after=p.maxHp;}
    else{stat='pulse';before=p.pulse;p.pulse+=24;after=p.pulse;}
    p.level++;game.event('salvage_upgrade_applied',{stat,beforeStat:before,afterStat:after});
    game.flash(C.cyan,.28);game.burst(p.x,p.y,{count:28,speed:220,size:4,life:.52,colors:[C.cyan,C.gold,C.white],gravity:0});
    GF.Sfx.melody([[440,.06],[660,.08],[880,.12]],{type:'triangle',vol:.16});
  },
  choose(which){
    if(this.phase!=='choice')return;this.choice=which;game.event('extraction_choice_made',{choice:which});
    GF.Sfx.melody([[523,.08],[784,.14]],{type:'triangle',vol:.18});
    if(which==='EXTRACT'){game.win({message:'EXTRACTION SECURED • SCORE '+game.score});return;}
    this.phase='bonus';this.titan=null;this.drones=[];this.hostile=[];this.bonusTime=25;
    for(let i=0;i<5;i++)this.spawnDrone(90+i*185,75+(i%2)*380,16);game.flash(C.pink,.22);
  },
  update(dt){
    const p=this.p,k=game.input.keys,q=game.input.pointer;this.ringSpin+=dt;this.musicTimer-=dt;
    if(this.musicTimer<=0){this.musicTimer=this.phase==='titan'?.68:1.15;GF.Sfx.beep({freq:this.phase==='titan'?125:180,to:this.phase==='titan'?150:220,dur:.08,type:'sine',vol:.02});}
    if(this.phase==='choice'){
      if(game.input.pressed('KeyE')||game.input.pressed('Enter')||game.input.pressed('Space')||(q.clicked&&q.x<480))this.choose('EXTRACT');
      else if(game.input.pressed('KeyR')||(q.clicked&&q.x>=480))this.choose('DESCEND');return;
    }
    let mx=(k.KeyD||k.ArrowRight?1:0)-(k.KeyA||k.ArrowLeft?1:0),my=(k.KeyS||k.ArrowDown?1:0)-(k.KeyW||k.ArrowUp?1:0),ml=Math.hypot(mx,my)||1;
    p.x=GF.math.clamp(p.x+mx/ml*255*dt,30,930);p.y=GF.math.clamp(p.y+my/ml*255*dt,76,500);p.fire-=dt;p.invuln=Math.max(0,p.invuln-dt);
    if(p.fire<=0&&(q.down||k.Space||this.shots.length===0))this.fire();
    this.spawnTimer+=dt;
    if(this.phase==='opening'&&(this.scoreKills>=1||game.time>3.2))this.spawnTitan();
    if(this.phase==='opening'&&this.spawnTimer>2.5){this.spawnTimer=0;this.spawnDrone(875,120+game.rng()*300,8);}
    if(this.phase==='bonus'){this.bonusTime-=dt;if(this.spawnTimer>1){this.spawnTimer=0;this.spawnDrone(60+game.rng()*840,game.rng()<.5?82:470,16);}if(this.bonusTime<=0)game.win({message:'DEEP FORGE SURVIVED • SCORE '+game.score});}
    for(let i=this.shots.length-1;i>=0;i--){const s=this.shots[i];s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;let hit=false;
      for(let j=this.drones.length-1;j>=0;j--){const d=this.drones[j];if(Math.hypot(s.x-d.x,s.y-d.y)<s.r+d.r){d.hp-=p.damage;d.flash=.14;hit=true;game.burst(s.x,s.y,{count:7,speed:110,size:2,life:.24,colors:[C.cyan,C.white],gravity:0});if(!this.attackSent&&game.time>1.25&&game.score>0){this.attackSent=true;game.event('attack_landed',{target:'drone',damage:p.damage});}if(d.hp<=0)this.killDrone(j);break;}}
      if(!hit&&this.titan&&!this.titan.dead&&Math.hypot(s.x-this.titan.x,s.y-this.titan.y)<s.r+this.titan.r){this.hitTitan();hit=true;}
      if(hit||s.life<=0||s.x<0||s.x>960||s.y<0||s.y>540)this.shots.splice(i,1);
    }
    for(const d of this.drones){let dx=p.x-d.x,dy=p.y-d.y,dd=Math.hypot(dx,dy)||1;d.x+=dx/dd*46*dt;d.y+=dy/dd*46*dt;d.flash=Math.max(0,d.flash-dt);d.fire-=dt;if(d.fire<=0){d.fire=this.phase==='bonus'?1:1.6;this.hostile.push({x:d.x,y:d.y,vx:dx/dd*175,vy:dy/dd*175,r:5,life:4});}if(dd<d.r+p.r+2)this.hurt(8,d.x,d.y);}
    const t=this.titan;if(t&&!t.dead){t.spin+=dt*.55;t.flash=Math.max(0,t.flash-dt);let dx=p.x-t.x,dy=p.y-t.y,dd=Math.hypot(dx,dy)||1;t.x+=dx/dd*18*dt;t.y+=dy/dd*18*dt;t.fire-=dt;t.stomp-=dt;
      if(t.fire<=0){t.fire=1.12;for(let n=-1;n<=1;n++){const a=Math.atan2(dy,dx)+n*.28;this.hostile.push({x:t.x,y:t.y,vx:Math.cos(a)*225,vy:Math.sin(a)*225,r:7,life:4});}}
      if(t.stomp<=0){t.stomp=3.05;game.shake(10,.34);game.flash(C.gold,.15);game.burst(t.x,t.y,{count:24,speed:230,size:4,life:.48,colors:[C.gold,C.pink],gravity:0});if(dd<190)this.hurt(13,t.x,t.y);GF.Sfx.noise({dur:.14,vol:.17,freq:240});}
      if(!this.titanSent&&game.time>1.25&&game.score>0&&(this.drones.length>0||this.hostile.length>0)){this.titanSent=true;game.event('titan_and_threats_active',{titan:'HEX-FRAME TITAN',threats:this.drones.length+this.hostile.length});}
    }
    for(let i=this.hostile.length-1;i>=0;i--){const s=this.hostile[i];s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(Math.hypot(s.x-p.x,s.y-p.y)<s.r+p.r){this.hurt(7,s.x,s.y);this.hostile.splice(i,1);}else if(s.life<=0||s.x<-20||s.x>980||s.y<-20||s.y>560)this.hostile.splice(i,1);}
    for(let i=this.shards.length-1;i>=0;i--){const z=this.shards[i];z.life-=dt;let dx=p.x-z.x,dy=p.y-z.y,dd=Math.hypot(dx,dy)||1;if(dd<270){z.vx+=dx/dd*650*dt;z.vy+=dy/dd*650*dt;}z.x+=z.vx*dt;z.y+=z.vy*dt;z.vx*=.97;z.vy*=.97;if(dd<25){this.salvage++;this.shards.splice(i,1);GF.Sfx.beep({freq:780,to:1100,dur:.05,type:'triangle',vol:.07});}else if(z.life<=0)this.shards.splice(i,1);}
    if(Math.hypot(p.x-480,p.y-300)<145)this.buyUpgrade();
    if(!this.hudSent&&game.score>0&&game.time>1.25){this.hudSent=true;game.event('hud_layout_clear',{coreRegion:'left',scoreSalvageRegion:'bottom_left',progressRegion:'right'});}
  },
  draw(ctx){
    const W=960,H=540,p=this.p;
    const bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#0B1B34');bg.addColorStop(.48,C.navy);bg.addColorStop(1,'#1A102B');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
    // Foundry walls and warm furnace haze create a strong arena silhouette.
    const haze=ctx.createRadialGradient(480,300,30,480,300,470);haze.addColorStop(0,'rgba(20,217,255,.07)');haze.addColorStop(.58,'rgba(255,59,129,.025)');haze.addColorStop(1,'rgba(0,0,0,.3)');ctx.fillStyle=haze;ctx.fillRect(0,0,W,H);
    ctx.fillStyle='rgba(255,191,63,.045)';ctx.fillRect(0,64,14,410);ctx.fillRect(946,64,14,410);
    ctx.strokeStyle='rgba(20,217,255,.13)';ctx.lineWidth=1;const off=(game.time*22)%40;
    for(let x=-40+off;x<W;x+=40){ctx.beginPath();ctx.moveTo(x,64);ctx.lineTo(x,H);ctx.stroke();}
    for(let y=64;y<H;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}
    ctx.strokeStyle='rgba(255,191,63,.14)';ctx.beginPath();ctx.moveTo(0,475);ctx.lineTo(W,475);ctx.stroke();
    for(let i=0;i<32;i++){const x=(i*137+game.time*(16+i%4*7))%W,y=72+(i*71)%398;ctx.fillStyle=i%3===0?'rgba(255,191,63,.48)':'rgba(20,217,255,.28)';ctx.fillRect(x,y,2,2);}
    // Forge Ring remains visible, making the upgrade location obvious.
    ctx.save();ctx.translate(480,300);ctx.rotate(this.ringSpin*.4);ctx.strokeStyle='rgba(20,217,255,.62)';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,94,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='rgba(255,191,63,.25)';ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,0,111,0,Math.PI*2);ctx.stroke();for(let a=0;a<6;a++){ctx.rotate(Math.PI/3);ctx.fillStyle=C.cyan;ctx.fillRect(86,-3,12,6);}ctx.restore();
    GF.Draw.text(ctx,'FORGE RING',480,412,{size:11,color:'rgba(20,217,255,.74)',weight:'700'});
    for(const z of this.shards){ctx.save();ctx.translate(z.x,z.y);ctx.rotate(game.time*5);ctx.shadowColor=C.gold;ctx.shadowBlur=12;ctx.fillStyle=C.gold;hex(ctx,0,0,6);ctx.fill();ctx.restore();}
    for(const s of this.shots){ctx.save();ctx.shadowColor=C.cyan;ctx.shadowBlur=15;ctx.fillStyle=C.white;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();ctx.strokeStyle=C.cyan;ctx.lineWidth=3;ctx.stroke();ctx.restore();}
    for(const s of this.hostile){ctx.save();ctx.shadowColor=C.pink;ctx.shadowBlur=12;ctx.fillStyle=C.pink;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();ctx.restore();}
    for(const d of this.drones){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(game.time*2);ctx.shadowColor=C.pink;ctx.shadowBlur=13;ctx.fillStyle=d.flash>0?C.white:C.pink;hex(ctx,0,0,15);ctx.fill();ctx.strokeStyle=C.cyan;ctx.lineWidth=2;ctx.stroke();ctx.fillStyle=C.navy;ctx.fillRect(-5,-5,10,10);ctx.restore();}
    const t=this.titan;if(t&&!t.dead){
      ctx.save();ctx.translate(t.x,t.y);ctx.rotate(t.spin);ctx.shadowColor=C.gold;ctx.shadowBlur=22;ctx.strokeStyle=t.flash>0?C.white:C.gold;ctx.lineWidth=7;ctx.beginPath();ctx.arc(0,0,54,0,Math.PI*2);ctx.stroke();
      for(let i=0;i<6;i++){ctx.rotate(Math.PI/3);ctx.fillStyle=C.pink;ctx.fillRect(42,-13,26,26);ctx.fillStyle=C.gold;ctx.fillRect(47,-7,16,4);}ctx.fillStyle=C.cyan;ctx.beginPath();ctx.arc(0,0,25,0,Math.PI*2);ctx.fill();ctx.fillStyle=C.white;ctx.beginPath();ctx.arc(0,0,9,0,Math.PI*2);ctx.fill();ctx.restore();
      GF.Draw.text(ctx,'⚠  HEX-FRAME TITAN  ⚠',t.x,t.y-87,{size:16,color:C.gold,weight:'800'});
      panel(ctx,320,137,320,18,'rgba(255,191,63,.5)');ctx.fillStyle='rgba(255,59,129,.22)';ctx.fillRect(325,142,310,8);ctx.fillStyle=C.pink;ctx.fillRect(325,142,310*GF.math.clamp(t.hp/t.max,0,1),8);
      GF.Draw.text(ctx,'ARMOR '+Math.max(0,Math.ceil(t.hp))+' / '+t.max,480,128,{size:12,color:C.white,weight:'700'});
    }
    ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.angle);ctx.shadowColor=C.cyan;ctx.shadowBlur=22;ctx.fillStyle=p.invuln>0?C.white:C.cyan;ctx.beginPath();ctx.arc(0,0,18+(p.level-1)*1.5,0,Math.PI*2);ctx.fill();ctx.fillStyle=C.navy;ctx.fillRect(0,-6,30,12);ctx.fillStyle=C.gold;ctx.beginPath();ctx.arc(0,0,8+p.level,0,Math.PI*2);ctx.fill();ctx.restore();
    // Three separated HUD regions: Core / score and salvage / progression.
    panel(ctx,18,76,238,61,'rgba(20,217,255,.72)');
    GF.Draw.text(ctx,'CORE INTEGRITY',31,91,{size:12,color:C.cyan,align:'left',weight:'800'});
    GF.Draw.text(ctx,Math.ceil(p.hp)+' / '+p.maxHp,243,91,{size:15,color:C.white,align:'right',weight:'800'});
    ctx.fillStyle='rgba(255,59,129,.28)';ctx.fillRect(31,106,211,12);ctx.fillStyle=C.cyan;ctx.fillRect(31,106,211*GF.math.clamp(p.hp/Math.max(1,p.maxHp),0,1),12);ctx.strokeStyle='rgba(234,251,255,.55)';ctx.strokeRect(31.5,106.5,210,11);
    panel(ctx,18,449,300,68,'rgba(255,191,63,.72)');
    GF.Draw.text(ctx,'SALVAGE  '+this.salvage,32,469,{size:18,color:C.gold,align:'left'});GF.Draw.text(ctx,'FORGE COST 3',303,469,{size:12,color:C.white,align:'right',weight:'700'});
    GF.Draw.text(ctx,'SPENT '+this.spent+'   •   CORE LEVEL '+p.level,32,495,{size:13,color:C.dim,align:'left',weight:'700'});
    panel(ctx,704,76,238,61,'rgba(255,59,129,.72)');
    GF.Draw.text(ctx,'RUN PROGRESS',718,91,{size:12,color:C.pink,align:'left',weight:'800'});
    const status=this.phase==='bonus'?'DESCENT '+Math.ceil(this.bonusTime)+'s':this.phase==='titan'?'TITAN BREACH':this.phase==='choice'?'DECISION READY':'DRONE SWEEP';
    GF.Draw.text(ctx,status,928,110,{size:15,color:C.white,align:'right',weight:'800'});GF.Draw.text(ctx,'DMG '+p.damage+'  •  PULSE '+p.pulse,928,126,{size:12,color:C.dim,align:'right',weight:'700'});
    if(this.phase==='choice'){ctx.fillStyle='rgba(3,8,20,.78)';ctx.fillRect(0,155,W,240);GF.Draw.text(ctx,'TITAN CORE BREACHED',480,190,{size:30,color:C.gold});GF.Draw.text(ctx,'BANK YOUR SALVAGE — OR FEED THE DEEP FORGE',480,222,{size:16,color:C.white,weight:'600'});GF.Draw.roundRect(ctx,135,255,300,104,16,'#123E58');GF.Draw.roundRect(ctx,525,255,300,104,16,'#511A39');GF.Draw.text(ctx,'EXTRACT',285,292,{size:30,color:C.cyan});GF.Draw.text(ctx,'E / SPACE • BANK RUN',285,328,{size:14,color:C.white});GF.Draw.text(ctx,'DESCEND',675,292,{size:30,color:C.pink});GF.Draw.text(ctx,'R • 25s • 2× SCORE',675,328,{size:14,color:C.white});}
    GF.Draw.vignette(ctx,W,H,.36);
  }
});
game.titleScreen({subtitle:'WASD / ARROWS MOVE • SPACE OR CLICK TO FIRE • ENTER THE FORGE RING'});
